using Microsoft.EntityFrameworkCore; using SupportAgent.Core.Models; using SupportAgent.Infrastructure.Services;
namespace SupportAgent.Tests;
public class ErpServiceTests
{
 [Fact] public void Calculator_uses_decimal_financial_truth(){var c=new InvoiceCalculator();Assert.Equal(205m,c.LineTotal(2,100,5,10));Assert.Equal(80m,c.Outstanding(100,[new Payment{Amount=20}]));}
 [Fact] public async Task Services_calculate_balance_and_low_stock(){await using var db=TestDbContextFactory.CreateContext(nameof(Services_calculate_balance_and_low_stock));db.Customers.Add(new Customer{Id=1,FirstName="A",LastName="B",Email="a@b.com"});var p=new Product{Id=1,Sku="S1",Name="Keyboard",UnitPrice=50,IsActive=true,Inventory=new InventoryItem{QuantityOnHand=2,ReorderLevel=5}};db.Products.Add(p);db.Invoices.Add(new Invoice{Id=1,CustomerId=1,InvoiceNumber="INV-1",Status="PartiallyPaid",IssueDate=DateTime.UtcNow,TotalAmount=100,Customer=null!,Payments=[new Payment{Amount=25,PaymentReference="P1"}],Items=[new InvoiceItem{Description="Item",Quantity=2,UnitPrice=50,LineTotal=100}]});await db.SaveChangesAsync();var invoice=new InvoiceService(db,new InvoiceCalculator());var b=await invoice.GetCustomerBalanceAsync(1);Assert.Equal(75,b.OutstandingBalance);Assert.True((await new InventoryService(db).GetInventoryAsync(1))!.LowStock);}
 [Fact] public async Task Pdf_contains_invoice_number(){await using var db=TestDbContextFactory.CreateContext(nameof(Pdf_contains_invoice_number));db.Customers.Add(new Customer{Id=1,FirstName="A",LastName="B",Email="a@b.com"});db.Invoices.Add(new Invoice{Id=1,CustomerId=1,InvoiceNumber="INV-PDF",Status="Issued",IssueDate=DateTime.UtcNow,TotalAmount=10,Items=[new InvoiceItem{Description="Service",Quantity=1,UnitPrice=10,LineTotal=10}]});await db.SaveChangesAsync();var bytes=await new InvoiceDocumentService(new InvoiceService(db,new InvoiceCalculator())).GenerateAsync(1);Assert.NotNull(bytes);Assert.True(bytes.Length>100);Assert.Contains("%PDF",System.Text.Encoding.ASCII.GetString(bytes,0,4));}
 [Fact] public async Task Development_seeder_targets_demo_tenant_without_authenticated_user(){await using var db=TestDbContextFactory.CreateContext(nameof(Development_seeder_targets_demo_tenant_without_authenticated_user));await TestDbContextFactory.SeedSampleDataAsync(db);db.Customers.Add(new Customer{Id=102,FirstName="Sarah",LastName="Khan",Email="sarah@example.com"});await db.SaveChangesAsync();await SupportAgent.Infrastructure.Data.ErpDevelopmentSeeder.SeedAsync(db);var invoices=await db.Invoices.IgnoreQueryFilters().OrderBy(x=>x.InvoiceNumber).ToListAsync();Assert.Equal(4,invoices.Count);Assert.All(invoices,x=>Assert.Equal(SupportAgent.Infrastructure.Data.TenantDefaults.DemoOrganizationId,x.OrganizationId));Assert.Equal(new[]{"INV-1001","INV-1002","INV-1003","INV-1004"},invoices.Select(x=>x.InvoiceNumber));}
}
